'use strict';
(() => {
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
home:'<path d="m3 10 9-7 9 7v10H5V10m4 10v-7h6v7"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',grammar:'<path d="M4 5h16M9 3v4M5 11h14M7 16h10M5 21h14M12 9v12"/>',read:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',headphones:'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 12H3v7h4v-7H4Zm16 0h1v7h-4v-7h3Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 3"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',chart:'<path d="M4 3v18h17M9 16v-5m5 5V7m5 9V4"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 5 5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',flame:'<path d="M13 2s2 6-2 9c-2-1-2-3-2-3s-5 5-4 10a7 7 0 0 0 13 0c2-5-1-9-1-9s0 4-2 5c2-7-2-12-2-12Z"/>',check:'<path d="m5 12 4 4L19 6"/>',leaf:'<path d="M20 3C8 1 1 8 5 17c9 4 16-2 15-14ZM3 21 16 7"/>',volume:'<path d="m11 4-6 5H2v6h3l6 5V4Zm4 4c3 2 3 6 0 8m3-11c5 4 5 10 0 14"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',repeat:'<path d="M20 7H7a4 4 0 0 0-4 4m17-4-4-4m4 4-4 4M4 17h13a4 4 0 0 0 4-4M4 17l4-4m-4 4 4 4"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>'};
const icon = n => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
$('#search-icon').innerHTML=icon('search');
const key='kotonoha-n1-v1';
let storageKey=key;
let cloud=null;
const emptyMemory=()=>({known:[],saved:[],activity:{},history:[],mistakes:[],custom:{grammar:[],vocab:[],kanji:[]},notes:{},active:null});
let memory=emptyMemory();
let storageOK=true;
try { const data=JSON.parse(localStorage.getItem(key)||'null'); if(data&&typeof data==='object')memory={...memory,...data}; }catch{storageOK=false;}
const save=()=>{try{localStorage.setItem(storageKey,JSON.stringify(memory));}catch{if(storageOK)toast('保存領域が利用できません。記録をバックアップしてください。');storageOK=false;}try{cloud?.changed(memory);}catch{toast('同期記録を準備できません。端末のバックアップを保存してください。');}};
const dayKey=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const today=()=>memory.activity[dayKey()]||{items:[],questions:[]};
const record=(id,kind='items')=>{const date=dayKey();memory.activity[date]||={items:[],questions:[]};memory.activity[date][kind]||=[];if(!memory.activity[date][kind].includes(id))memory.activity[date][kind].push(id);save();};
const sources=window.KNOWLEDGE||{grammar:[],vocab:[],kanji:[]};
const courses=[{key:'kanji',name:'文字',sub:'漢字・読み方',icon:'字',desc:'読みを知り、ことばの輪郭をつかむ。'},{key:'vocab',name:'語彙',sub:'意味・使い分け',icon:'book',desc:'豊かな表現を、文脈とともに。'},{key:'grammar',name:'文法',sub:'文型・表現',icon:'grammar',desc:'文のしくみから、深い理解へ。'},{key:'reading',name:'読解',sub:'文章理解',icon:'read',desc:'行間を読み、筆者の意図をつかむ。'},{key:'listening',name:'聴解',sub:'聞き取り',icon:'headphones',desc:'自然な日本語から、必要な情報を。'}];
const knowledge=type=>[...(sources[type]||[]),...(memory.custom?.[type]||[])];
const builtInItems=['kanji','vocab','grammar'].flatMap(type=>(sources[type]||[]).map(item=>({...item,type})));
const builtInIndex=new Map(builtInItems.map(item=>[item.id,item]));
const allKnowledge=()=>[...builtInItems,...['kanji','vocab','grammar'].flatMap(type=>(memory.custom?.[type]||[]).map(item=>({...item,type})))];
const isLatestAddition=x=>/^(vc|vd|vf|gf|kf)\d/.test(x.id);
const isPreviousAddition=x=>/^(ge|va|vb|ke)\d/.test(x.id);
const focusOf=x=>String(x.focus||'').startsWith('関連')?'関連知識':'N1対策';
const nameOf=type=>courses.find(c=>c.key===type)?.name||'学習';
const getItem=id=>{if(builtInIndex.has(id))return builtInIndex.get(id);for(const type of ['kanji','vocab','grammar']){const item=(memory.custom?.[type]||[]).find(x=>x.id===id);if(item)return {...item,type};}return undefined;};
const reading=()=>window.EXAMS?.reading||[];
const listening=()=>window.EXAMS?.listening||[];
const language=()=>window.LANGUAGE_EXAM||window.EXAMS?.language||[];
let toastTimeout;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
const titles={home:'ホーム',kanji:'文字',vocab:'語彙',grammar:'文法',reading:'読解',listening:'聴解',exam:'模擬試験',review:'復習ノート',progress:'学習記録',about:'この学習室について'};
function currentRoute(){return (location.hash.slice(1)||'home').split('?')[0];}
function nav(){const items=[['home','home','ホーム'],['kanji','grid','文字'],['vocab','book','語彙'],['grammar','grammar','文法'],['reading','read','読解'],['listening','headphones','聴解'],['sep'],['exam','clock','模擬試験'],['review','bookmark','復習ノート'],['progress','chart','学習記録']];$('#main-nav').innerHTML=items.map(([route,ic,label])=>route==='sep'?'<div class="nav-separator"></div>':`<a class="nav-link ${currentRoute()===route?'active':''}" href="#${route}" ${currentRoute()===route?'aria-current="page"':''}>${icon(ic)}${label}</a>`).join('');}
let catalog={query:'',status:'all',category:'all',focus:'all',page:0};let lastRoute='';let studyList=[],studyIndex=0;let reviewedResult=null;let reviewCursor=0;
function heading(label,title,desc=''){return `<div class="page-heading"><div class="eyebrow">${label}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`;}
function activeNotice(){return memory.active?`<div class="notice">模擬試験が進行中です。画面を移動しても計時は続きます。 <a class="text-link" href="#exam">試験に戻る →</a></div>`:'';}
function render(){nav();const route=currentRoute();$('#page-name').textContent=titles[route]||'ホーム';document.title=`${titles[route]||'ホーム'} — 言の葉 N1`;if(route!==lastRoute){catalog={query:'',status:'all',category:'all',focus:'all',page:0};lastRoute=route;}$('#sidebar').classList.remove('open');$('.mobile-backdrop')?.classList.remove('show');if('speechSynthesis' in window)speechSynthesis.cancel();switch(route){case'kanji':case'vocab':case'grammar':renderCatalog(route);break;case'reading':case'listening':renderPracticeLanding(route);break;case'exam':if(memory.active)renderActive();else if(reviewedResult)renderResult(reviewedResult);else renderExamLanding();break;case'review':renderReview();break;case'progress':renderProgress();break;case'about':renderAbout();break;default:renderHome();}if(!storageOK&&!$('.save-warning')){const w=document.createElement('div');w.className='save-warning';w.textContent='ブラウザーへの保存が利用できません。記録はこの画面内のみで有効です。';$('.topbar').after(w);}}
const main=html=>{$('#main').innerHTML=html;};
function streak(){let count=0,d=new Date();if(!memory.activity[dayKey(d)])d.setDate(d.getDate()-1);for(let i=0;i<3660;i++){const a=memory.activity[dayKey(d)];if(!a||!(a.items?.length||a.questions?.length))break;count++;d.setDate(d.getDate()-1);}return count;}
function weekHTML(){const start=new Date();const wd=(start.getDay()+6)%7;start.setDate(start.getDate()-wd);return `<div class="week-panel"><div class="week-row"><div class="week-title">今週のあしあと<small>小さな一歩を、毎日の習慣に。</small></div>${['月','火','水','木','金','土','日'].map((n,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const a=memory.activity[dayKey(d)];const learned=a&&(a.items?.length||a.questions?.length);return `<div class="day">${n}<i class="${learned?'active':dayKey(d)===dayKey()?'today':''}">${learned?'✓':d.getDate()}</i></div>`;}).join('')}</div></div>`;}
function renderHome(){const total=allKnowledge().length,known=memory.known.filter(id=>getItem(id)).length,ta=today();const v=ta.items.filter(id=>getItem(id)?.type==='vocab').length,g=ta.items.filter(id=>getItem(id)?.type==='grammar').length,r=ta.questions.filter(id=>id.startsWith('r')).length;const tasks=[v>=10,g>=5,r>=1];const date=new Intl.DateTimeFormat('ja-JP',{year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date());const featured=knowledge('grammar')[0];main(`${activeNotice()}<div class="welcome-line"><span class="greeting">${icon('sun')}おかえりなさい。今日も、一歩ずつ。</span><span class="date-tag">${esc(date)}</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">ことばを育てる、毎日の時間</div><h1>日々の積み重ねが、<br>N1への道になる。</h1><p>知る、使う、確かめる。自分のペースで、着実に。<br>あなたの日本語に、もうひとつの自信を。</p><div class="hero-actions"><button class="button" data-start-daily>今日の学習をはじめる ${icon('arrow')}</button><a class="button ghost" href="#progress">学習記録を見る ↗</a></div></div><div class="hero-art" aria-hidden="true"><div class="floating-note">一日一歩</div><div class="orbit"><span class="hero-kanji">積</span><i class="leaf"></i><i class="leaf two"></i><i class="leaf three"></i></div><div class="hero-vertical">小さな学び、大きな力。</div><div class="art-caption">ことばと、ともに育つ。</div></div></section><section class="stats" aria-label="学習状況"><div class="stat"><div class="stat-icon">${icon('flame')}</div><div><div class="stat-label">連続学習</div><div class="stat-value">${streak()}<small>日</small></div></div><span class="stat-aside">今日も続けよう</span></div><div class="stat"><div class="stat-icon">${icon('book')}</div><div><div class="stat-label">習得した知識</div><div class="stat-value">${known.toLocaleString()}<small>項目</small></div></div><span class="stat-aside">全 ${total} 項目</span></div><div class="stat"><div class="stat-icon">${icon('target')}</div><div><div class="stat-label">今日の学び</div><div class="stat-value">${ta.items.length+ta.questions.length}<small>項目・問</small></div></div><span class="stat-aside">ひとつずつ、着実に</span></div></section><div class="dashboard-grid"><div><div class="section-heading"><h2>学習コース<small>五つの力を、バランスよく。</small></h2><a class="text-link" href="#about">収録範囲 ↗</a></div><div class="course-grid">${courses.map((c,i)=>{const data=knowledge(c.key),learned=data.filter(x=>memory.known.includes(x.id)).length;return `<a class="course-card ${i===4?'wide':''}" href="#${c.key}"><div class="course-icon">${c.icon==='字'?'字':icon(c.icon)}</div><div><h3>${c.name}<small>${c.sub}</small></h3><p class="course-description">${c.desc}</p></div>${i<3?`<div class="course-meta"><span>${data.length} 項目・日本語解説</span><span>${learned} 項目習得</span></div><div class="mini-progress"><span style="width:${data.length?learned/data.length*100:0}%"></span></div>`:`<div class="course-meta"><span>オリジナル模擬問題</span><span>${i===3?reading().length:listening().length} 問</span></div>`}<span class="card-arrow">↗</span></a>`;}).join('')}</div>${weekHTML()}</div><div class="right-column"><section class="panel"><div class="panel-title">今日の小さな目標 <span>${tasks.filter(Boolean).length} / 3</span></div>${[{title:'語彙を10個、覚えよう',detail:`新しいことばとの出会い　${Math.min(v,10)} / 10`,route:'vocab'},{title:'文法を5つ、深めよう',detail:`使い方まで、しっかりと　${Math.min(g,5)} / 5`,route:'grammar'},{title:'読解を1問、解いてみよう',detail:`文章と向き合うひととき　${Math.min(r,1)} / 1`,route:'reading'}].map((x,i)=>`<a class="task ${tasks[i]?'done':''}" href="#${x.route}"><span class="task-check">${tasks[i]?'✓':''}</span><div>${x.title}<small>${x.detail}</small></div><span class="task-arrow">›</span></a>`).join('')}<div class="task-progress">今日の達成度<div class="mini-progress"><span style="width:${tasks.filter(Boolean).length/3*100}%"></span></div>${Math.round(tasks.filter(Boolean).length/3*100)}%</div></section><section class="daily-expression"><div class="panel-title">今日の文法 <span>ことばの引き出し</span></div><div class="expression">${esc(featured?.title||'〜に至るまで')}</div><div class="expression-meaning">${esc(featured?.jp||'細かな範囲まで含むことを表す。')}</div><a href="#grammar" ${featured?`data-item="${esc(featured.id)}"`:''}>例文と使い方を見る →</a></section></div></div>`);}
function renderCatalog(type){const data=knowledge(type),categories=[...new Set(data.map(x=>x.category))].filter(Boolean),filtered=data.filter(x=>{const q=catalog.query.toLowerCase();return (!q||[x.title,x.reading,x.jp,x.example].some(v=>String(v||'').toLowerCase().includes(q)))&&(catalog.category==='all'||x.category===catalog.category)&&(catalog.focus==='all'||focusOf(x)===catalog.focus)&&(catalog.status==='all'||catalog.status==='known'&&memory.known.includes(x.id)||catalog.status==='new'&&!memory.known.includes(x.id)||catalog.status==='saved'&&memory.saved.includes(x.id)||catalog.status==='expanded'&&isLatestAddition(x)||catalog.status==='previous'&&isPreviousAddition(x));});const size=12,count=Math.max(1,Math.ceil(filtered.length/size));catalog.page=Math.min(catalog.page,count-1);const desc={kanji:'漢字の読み・意味・熟語を、日本語の解説と例文で。',vocab:'意味と使い分けを、自然な日本語の例文とともに。',grammar:'接続・ニュアンス・例文から、文型を自分のものに。'};main(`${heading('ことばを知る・深める',nameOf(type),desc[type])}${activeNotice()}<div class="toolbar"><div class="local-search">${icon('search')}<input id="catalog-search" type="search" placeholder="ことば・読み方・意味で検索" value="${esc(catalog.query)}" aria-label="${nameOf(type)}を検索"></div><select id="category-filter" aria-label="分類"><option value="all">すべての分類</option>${categories.map(c=>`<option ${catalog.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="focus-filter" aria-label="学習範囲"><option value="all">すべての学習範囲</option><option value="N1対策" ${catalog.focus==='N1対策'?'selected':''}>N1対策の重点</option><option value="関連知識" ${catalog.focus==='関連知識'?'selected':''}>関連・基礎の補強</option></select><button class="button secondary" id="start-study">カードで学ぶ ${icon('arrow')}</button></div><div class="filter-tabs">${[['all','すべて'],['expanded','今回の追加'],['previous','前回の追加'],['new','未習得'],['known','習得済み'],['saved','保存した項目']].map(([s,label])=>`<button class="filter-tab ${catalog.status===s?'active':''}" data-filter="${s}">${label}</button>`).join('')}</div><div class="catalog-info"><span>${filtered.length} 項目 ${catalog.query?'の検索結果':''}</span><span>日本語解説・日本語例文付き</span></div><div class="knowledge-grid">${filtered.slice(catalog.page*size,(catalog.page+1)*size).map(cardHTML).join('')||'<div class="empty"><h3>該当する項目がありません</h3><p>検索することばや条件を変えてみましょう。</p></div>'}</div>${count>1?`<div class="pagination"><button data-page="-1" ${catalog.page===0?'disabled':''}>← 前へ</button><span>${catalog.page+1} / ${count}</span><button data-page="1" ${catalog.page===count-1?'disabled':''}>次へ →</button></div>`:''}<div class="notice">重点項目と関連する基礎知識を収録しています。「N1対策」は編集上の学習目安で、公式のレベル指定ではありません。<a href="#about" class="text-link">収録内容と拡張方法 →</a></div>`);$('#catalog-search').addEventListener('input',e=>{const pos=e.target.selectionStart;catalog.query=e.target.value;catalog.page=0;renderCatalog(type);const input=$('#catalog-search');input.focus();input.setSelectionRange(pos,pos);});$('#category-filter').onchange=e=>{catalog.category=e.target.value;catalog.page=0;renderCatalog(type);};$('#focus-filter').onchange=e=>{catalog.focus=e.target.value;catalog.page=0;renderCatalog(type);};$('#start-study').onclick=()=>startStudy(filtered);}
function cardHTML(x){return `<article class="knowledge-card"><div class="card-tags"><span class="badge">${esc(x.category)}</span><span class="scope-tag ${focusOf(x)==='関連知識'?'related':''}">${focusOf(x)}</span></div><button class="bookmark ${memory.saved.includes(x.id)?'saved':''}" data-save="${esc(x.id)}" aria-label="${memory.saved.includes(x.id)?'保存を解除':'復習用に保存'}">${icon('bookmark')}</button><h3><a href="#${x.type||currentRoute()}" data-item="${esc(x.id)}">${esc(x.title)}</a></h3><div class="reading">${esc(x.reading||x.connection||'N1 文型')}</div><div class="meaning">${esc(x.jp)}</div><div class="card-bottom"><span class="${memory.known.includes(x.id)?'known-label':''}">${memory.known.includes(x.id)?'✓ 習得済み':'日本語解説'}</span><a href="#${x.type||currentRoute()}" data-item="${esc(x.id)}">詳しく学ぶ ↗</a></div></article>`;}
function startStudy(list,id){studyList=list.length?list:allKnowledge();studyIndex=id?studyList.findIndex(x=>x.id===id):0;if(studyIndex<0)studyIndex=0;if(!studyList.length)return toast('学習項目がありません。');showStudy();}
function showStudy(){const x=studyList[studyIndex];const known=memory.known.includes(x.id),saved=memory.saved.includes(x.id);$('#study-dialog').innerHTML=`<button class="dialog-close" data-close-study aria-label="閉じる">×</button><span class="badge">${nameOf(x.type||currentRoute())} / ${esc(x.category)}</span><span class="scope-tag study-scope">${focusOf(x)} · 編集上の学習目安</span><h2>${esc(x.title)}</h2><p class="study-reading">${esc(x.reading||x.connection||'')}</p>${x.connection&&x.connection!==x.reading?`<div class="definition"><label>接続</label><p>${esc(x.connection)}</p></div>`:''}<div class="definition"><label>日本語の解説</label><p>${esc(x.jp)}</p></div><div class="example-block"><label>日本語の例文</label><p>${esc(x.example)}</p></div>${noteEditorHTML(x.id)}<div class="study-actions"><button class="voice-button" data-speak-example aria-label="例文を聞く">${icon('volume')}</button><button class="button secondary" data-toggle-known>${known?'✓ 習得済みを解除':'覚えた ✓'}</button><button class="button" data-study-next>次の項目 ${icon('arrow')}</button><button class="voice-button" data-toggle-save aria-label="${saved?'保存を解除':'保存する'}">${icon('bookmark')}</button></div><div class="study-counter">${studyIndex+1} / ${studyList.length}　·　習得を記録すると、今日の学びに反映されます。</div>`;bindNoteEditor(x.id,$('#study-dialog'));if(!$('#study-dialog').open)$('#study-dialog').showModal();$('[data-close-study]').onclick=()=>{$('#study-dialog').close();render();};$('[data-speak-example]').onclick=()=>speak(x.example);$('[data-toggle-save]').onclick=()=>{toggleSave(x.id);showStudy();};$('[data-toggle-known]').onclick=()=>{if(memory.known.includes(x.id))memory.known=memory.known.filter(id=>id!==x.id);else{memory.known.push(x.id);record(x.id);}save();showStudy();};$('[data-study-next]').onclick=()=>{if(studyIndex+1===studyList.length){toast('このセットの最後です。もう一度、最初から学べます。');studyIndex=0;}else studyIndex++;if('speechSynthesis'in window)speechSynthesis.cancel();showStudy();};}
function toggleSave(id){if(memory.saved.includes(id))memory.saved=memory.saved.filter(i=>i!==id);else memory.saved.push(id);save();toast(memory.saved.includes(id)?'復習ノートに保存しました。':'保存を解除しました。');}
$('#study-dialog').addEventListener('close',()=>{if('speechSynthesis'in window)speechSynthesis.cancel();render();});
let voiceTimer=null,voiceRun=0;
function speak(text,rate=1,onend){if(!('speechSynthesis'in window)){toast('このブラウザーは音声読み上げに対応していません。');return;}speechSynthesis.cancel();const run=++voiceRun;const utter=new SpeechSynthesisUtterance(text);utter.lang='ja-JP';utter.rate=rate;const voice=speechSynthesis.getVoices().find(v=>v.lang==='ja-JP')||speechSynthesis.getVoices().find(v=>v.lang.startsWith('ja'));if(voice)utter.voice=voice;const s=$('#audio-status');if(s)s.textContent='読み上げ中…';utter.onend=()=>{if(run!==voiceRun)return;if(s)s.textContent='再生が終わりました。';onend?.();};utter.onerror=e=>{if(run!==voiceRun)return;if(s)s.textContent='音声を再生できませんでした。端末の日本語音声を確認してください。';if(e.error!=='interrupted'&&e.error!=='canceled')toast('日本語音声を再生できません。端末の音声設定を確認してください。');};speechSynthesis.speak(utter);clearInterval(voiceTimer);voiceTimer=setInterval(()=>{if(!speechSynthesis.speaking){clearInterval(voiceTimer);return;}if(!speechSynthesis.paused){speechSynthesis.pause();speechSynthesis.resume();}},10000);}
function stopVoice(){voiceRun++;clearInterval(voiceTimer);if('speechSynthesis'in window)speechSynthesis.cancel();const s=$('#audio-status');if(s)s.textContent='再生を停止しました。';}
function renderPracticeLanding(type){const isRead=type==='reading';const q=isRead?reading():listening();const groups=[...new Set(q.map(x=>x.category))];main(`${heading(isRead?'読む力を、確かな力に':'耳から広がる、日本語の世界',nameOf(type),isRead?'文章の構成と筆者の意図を、じっくり読み解く。':'会話の流れから、要点と意図を聞き取る。')}${activeNotice()}<section class="exam-banner"><div class="big-icon">${icon(isRead?'read':'headphones')}</div><div><h2>本番の形式に、一歩近づく。</h2><p>${isRead?'評論・随筆・案内文。六つの出題形式に対応。':'課題理解から統合理解まで、五つの出題形式に対応。'}</p></div></section><div class="exam-grid"><section class="exam-card"><span class="badge">${isRead?'読解・分野別練習':'聴解・計時練習'}</span><h2>${isRead?'読解トレーニング':'聴解トレーニング'}</h2><p>${isRead?'独立した読解練習として、60分の学習用タイマーを設定。実際の試験では言語知識と合わせて110分です。':'試験の参考問題数に合わせた30問。55分のタイマーで、合成音声を聞いて答えます。'}</p><div class="exam-numbers"><div><b>${q.length}</b><span>問</span><small>オリジナル問題</small></div><div><b>${isRead?60:55}</b><span>分</span><small>${isRead?'学習用の目安':'現行の試験時間'}</small></div></div><div class="exam-types">${groups.map(x=>`<span class="badge">${esc(x)}</span>`).join('')}</div><button class="button" data-start-exam="${type}">練習をはじめる ${icon('arrow')}</button></section><section class="exam-card"><span class="badge">形式別に、じっくり</span><h2>ひとつの形式に取り組む</h2><p>短いセットで、自分の苦手を見つけましょう。制限時間のない練習です。セットを提出すると解答と中日解説を確認できます。</p><div class="exam-types">${groups.map(x=>`<button class="filter-tab" data-category-practice="${esc(x)}" data-kind="${type}">${esc(x)} · ${q.filter(y=>y.category===x).length}問 →</button>`).join('')}</div><p>※ 初回は各形式を一つずつ学んでから、通し練習に挑戦するのがおすすめです。</p></section></div><div class="notice">${isRead?'実際の試験に合わせた110分の練習は「模擬試験」で利用できます。':'音声はブラウザーの日本語合成音声です。公式録音ではありません。日本語音声のある端末をご利用ください。音声確認は計時前に行えます。'}<br>本教材は独自に作成した模擬問題です。公式の過去問ではありません。</div>${!isRead?`<button class="button secondary" id="test-audio">${icon('volume')} 音声を確認する</button>`:''}`);if($('#test-audio'))$('#test-audio').onclick=()=>speak('日本語の音声を確認します。準備ができたら、練習を始めてください。');}
const modeNames={full:'N1 総合模擬試験',written:'言語知識・読解',reading:'読解トレーニング',listening:'聴解トレーニング',practice:'形式別練習',mistakes:'間違えた問題の復習'};
function renderExamLanding(){main(`${heading('知識を、実力に変える','模擬試験','本番を意識した時間配分で、今の力を確かめましょう。')}<section class="exam-banner"><div class="big-icon">${icon('clock')}</div><div><h2>いつもの学びを、本番の自信に。</h2><p>解答は自動保存。制限時間が終わると、その科目が自動で提出されます。</p></div></section><div class="exam-grid"><section class="exam-card"><span class="badge">本番の二科目を、通して練習</span><h2>N1 総合模擬試験</h2><p>言語知識・読解110分 → 科目間の準備 → 聴解55分。科目の提出後は、その科目の解答を変更できません。</p><div class="exam-numbers"><div><b>${language().length+reading().length+listening().length}</b><span>問</span><small>参考問題数に準拠</small></div><div><b>165</b><span>分</span><small>110分 ＋ 55分</small></div></div><button class="button" data-start-exam="full">総合模試をはじめる ${icon('arrow')}</button></section><section class="exam-card"><span class="badge">一科目ずつ、着実に</span><h2>言語知識・読解</h2><p>文字・語彙25問、文法20問、読解26問の計71問。言語知識と読解で、一つの110分タイマーを使います。</p><div class="exam-numbers"><div><b>${language().length+reading().length}</b><span>問</span><small>三つの力を測る</small></div><div><b>110</b><span>分</span><small>本番の試験時間</small></div></div><button class="button secondary" data-start-exam="written">この科目に取り組む ${icon('arrow')}</button></section></div><div class="notice">問題数は公式資料の「目安」に合わせています（実際の実施回で変わる場合があります）。聴解は2022年12月以降の30問・55分に対応。結果は正答数・正答率です。JLPTの尺度得点や合否を算出するものではありません。<br>聴解は合成音声で再生します。試験前に <button class="text-link" id="test-audio">音声を確認 →</button></div><a class="button secondary" href="#listening">${icon('headphones')} 聴解だけを練習する</a>${memory.history.length?`<section class="history-list"><div class="section-heading"><h2>これまでの挑戦</h2><a class="text-link" href="#progress">すべて見る →</a></div>${memory.history.slice(0,3).map(historyHTML).join('')}</section>`:''}`);$('#test-audio').onclick=()=>speak('日本語の音声を確認します。会話を聞いて、最もよい答えを選んでください。');}
function sectionData(active=memory.active){if(!active)return [];if(active.customQuestions)return active.customQuestions;return active.mode==='full'?(active.section===0?[...language(),...reading()]:listening()):active.mode==='written'?[...language(),...reading()]:active.mode==='reading'?reading():listening();}
function startExam(mode,customQuestions){if(memory.active){location.hash='exam';renderActive();toast('進行中の試験に戻りました。');return;}const timed=['full','written','reading','listening'].includes(mode);const minutes=mode==='reading'?60:mode==='listening'?55:110;memory.active={id:`attempt-${Date.now()}`,mode,section:0,phase:'running',cursor:0,answers:{},flags:[],deadline:timed?Date.now()+minutes*60000:null,startedAt:Date.now(),parts:[],customQuestions:customQuestions||null};reviewedResult=null;save();stopVoice();if(location.hash!=='#exam')location.hash='exam';else renderActive();}
function renderActive(){const a=memory.active;if(!a)return renderExamLanding();if(a.phase==='break'){main(`${heading('ひとつ目の科目、おつかれさまでした','聴解の準備をしましょう。')}<div class="exam-banner"><div class="big-icon">${icon('headphones')}</div><div><h2>次の科目：聴解 30問・55分</h2><p>言語知識・読解の解答は確定しました。聴解を始めると55分の計時を開始します。</p></div></div><div class="notice">端末の音量と日本語の合成音声を確認してください。画面上の「音声を再生」から会話を聞きます。試験中に画面を閉じてもタイマーは進みます。</div><div class="hero-actions"><button class="button secondary" id="test-audio">${icon('volume')} 音声を確認する</button><button class="button" id="start-next-section">聴解をはじめる ${icon('arrow')}</button></div><button class="button ghost" id="abandon-exam">試験を終了する</button>`);$('#test-audio').onclick=()=>speak('音声の確認です。次は聴解の問題です。');$('#start-next-section').onclick=()=>{stopVoice();a.section=1;a.cursor=0;a.phase='running';a.answers={};a.flags=[];a.deadline=Date.now()+55*60000;save();renderActive();};$('#abandon-exam').onclick=abandonExam;return;}const questions=sectionData();if(!questions.length){main('<div class="empty">問題データを読み込めませんでした。ページを再読み込みしてください。</div>');return;}a.cursor=Math.min(a.cursor,questions.length-1);const q=questions[a.cursor];const answered=Object.keys(a.answers).filter(id=>questions.some(x=>x.id===id)).length;const audio=!!q.script;main(`<div class="exam-top"><h2>${esc(modeNames[a.mode])}<br><span style="color:#96a389;font-size:9px">${a.mode==='full'?(a.section===0?'科目1：言語知識・読解':'科目2：聴解'):a.mode==='reading'?'学習用60分・本試験の科目時間ではありません':'オリジナル模擬問題'}</span></h2><span class="timer" id="exam-timer">${a.deadline?formatTime(a.deadline-Date.now()):'時間制限なし'}</span><button class="button" id="submit-exam">${a.mode==='full'&&a.section===0?'科目を提出':'解答を提出'}</button></div><div class="exam-layout"><section class="question-paper"><div class="question-head"><b>問 ${a.cursor+1}</b><span class="badge">${esc(q.category)}</span><button class="flag-button ${a.flags.includes(q.id)?'active':''}" id="flag-question" style="margin-left:auto">${a.flags.includes(q.id)?'✓ あとで確認':'あとで確認'}</button></div>${audio?`<div class="audio-box">${icon('headphones')}<div class="audio-controls"><button class="button" id="play-audio">${icon('play')} 音声を再生</button><button class="button secondary" id="stop-audio">停止</button><select id="audio-rate" aria-label="再生速度"><option value="1">1.0倍速</option><option value="0.85">0.85倍速</option><option value="1.15">1.15倍速</option></select></div><p>日本語合成音声 · 文章は提出後に表示されます</p><div id="audio-status" class="audio-status" role="status"></div></div>`:''}${q.passage?`<div class="passage">${esc(q.passage)}</div>`:''}<p class="question-text">${esc(q.question)}</p><div role="radiogroup" aria-label="解答の選択肢">${q.options.map((v,i)=>`<button class="option ${a.answers[q.id]===i?'selected':''}" role="radio" aria-checked="${a.answers[q.id]===i}" data-answer="${i}"><span class="option-num">${i+1}</span><span>${esc(v)}</span></button>`).join('')}</div><div class="question-nav"><button class="button secondary" data-question-step="-1" ${a.cursor===0?'disabled':''}>← 前の問題</button><button class="button" data-question-step="1" ${a.cursor===questions.length-1?'disabled':''}>次の問題 ${icon('arrow')}</button></div></section><aside class="question-map"><h3>解答状況 <span id="answered-count">${answered}</span> / ${questions.length}</h3><div class="map-grid">${questions.map((x,i)=>`<button class="${i===a.cursor?'current':''} ${a.answers[x.id]!==undefined?'answered':''} ${a.flags.includes(x.id)?'flagged':''}" data-question-index="${i}" aria-label="問題${i+1}${a.answers[x.id]!==undefined?' 解答済み':' 未解答'}">${i+1}</button>`).join('')}</div><div class="map-legend">緑：解答済み　枠線：現在の問題<br>•：あとで確認<br>画面を離れても、計時は続きます。</div><button class="text-link" id="abandon-exam" style="margin-top:15px">試験を終了する</button></aside></div>`);$('#submit-exam').onclick=async()=>{const remaining=questions.length-answered;if(await confirmDialog('解答を提出しますか？',`${remaining?`未解答が${remaining}問あります。未解答は不正解として集計されます。`: 'すべての問題に解答しています。'}提出後は、この科目の解答を変更できません。`,'提出する'))finishSection();};$('#flag-question').onclick=()=>{a.flags=a.flags.includes(q.id)?a.flags.filter(id=>id!==q.id):[...a.flags,q.id];save();renderActive();};$('#abandon-exam').onclick=abandonExam;if(audio){$('#play-audio').onclick=()=>speak(q.script,Number($('#audio-rate').value));$('#stop-audio').onclick=stopVoice;}}
function formatTime(ms){const seconds=Math.max(0,Math.ceil(ms/1000));return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
async function abandonExam(){if(await confirmDialog('試験を終了しますか？','ここまでの解答を提出し、未解答は不正解として集計します。総合模試では未受験科目も未解答になります。','終了して集計')){const a=memory.active;if(!a)return;if(a.phase==='running')a.parts.push({questions:sectionData(),answers:{...a.answers}});if(a.mode==='full'&&a.section===0)a.parts.push({questions:listening(),answers:{}});completeExam();}}
function finishSection(){const a=memory.active;if(!a||a.phase!=='running')return;stopVoice();$('#confirm-dialog').open&&$('#confirm-dialog').close();a.parts.push({questions:sectionData(),answers:{...a.answers}});if(a.mode==='full'&&a.section===0){a.phase='break';a.deadline=null;save();if(currentRoute()==='exam')renderActive();else toast('最初の科目が終了しました。「模擬試験」で聴解を開始してください。');return;}completeExam();}
function completeExam(){const a=memory.active;if(!a)return;const questions=a.parts.flatMap(p=>p.questions);const answers=Object.assign({},...a.parts.map(p=>p.answers));let correct=0;questions.forEach(q=>{record(q.id,'questions');if(answers[q.id]===q.answer){correct++;memory.mistakes=memory.mistakes.filter(x=>x.id!==q.id);}else{const old=memory.mistakes.find(x=>x.id===q.id);if(old){old.question=q;old.selected=answers[q.id]??null;old.date=dayKey();}else memory.mistakes.push({id:q.id,question:q,selected:answers[q.id]??null,date:dayKey()});}});const result={id:a.id,mode:a.mode,date:new Date().toISOString(),correct,total:questions.length,questions,answers,elapsed:Math.round((Date.now()-a.startedAt)/1000)};memory.history.unshift(result);memory.history=memory.history.slice(0,30);memory.active=null;save();stopVoice();reviewedResult=result;location.hash='exam';renderResult(result);}
setInterval(()=>{const a=memory.active;if(!a||a.phase!=='running'||!a.deadline)return;const left=a.deadline-Date.now();const el=$('#exam-timer');if(el){el.textContent=formatTime(left);el.classList.toggle('danger',left<5*60000);}if(left<=0)finishSection();},1000);
function renderResult(r){const byCategory=[...new Set(r.questions.map(q=>q.category))];main(`${heading('挑戦を、次の学びへ','おつかれさまでした。')}<div class="results-hero"><h1>${esc(modeNames[r.mode]||'練習結果')}</h1><div class="result-score">${r.correct}<small> / ${r.total} 問</small></div><p>正答率 ${r.total?Math.round(r.correct/r.total*100):0}% · ${new Intl.DateTimeFormat('ja-JP',{dateStyle:'medium',timeStyle:'short'}).format(new Date(r.date))}</p><div class="result-actions"><button class="button" id="review-all">解答と解説を見る ${icon('arrow')}</button><a class="button secondary" href="#review">間違えた問題を復習</a><button class="button secondary" id="back-exam">模擬試験一覧</button></div></div><div class="section-heading"><h2>出題形式ごとの結果</h2><span class="badge">正答数 / 問題数</span></div>${byCategory.map(c=>{const qs=r.questions.filter(q=>q.category===c);return `<div class="result-row"><span>${esc(c)}</span><b>${qs.filter(q=>r.answers[q.id]===q.answer).length} / ${qs.length}</b></div>`;}).join('')}<div class="notice">正答率は学習のための参考値です。JLPTの尺度得点・合格判定とは異なります。間違えた問題と未解答の問題は「復習ノート」に保存しました。</div><div id="result-review"></div>`);$('#review-all').onclick=()=>{reviewCursor=0;renderQuestionReview(r);$('#result-review').scrollIntoView({behavior:'smooth',block:'start'});};$('#back-exam').onclick=()=>{reviewedResult=null;renderExamLanding();};}
function renderQuestionReview(r){const q=r.questions[reviewCursor],selected=r.answers[q.id];$('#result-review').innerHTML=`<section class="question-paper"><div class="question-head"><b>問 ${reviewCursor+1} / ${r.questions.length}</b><span class="badge">${esc(q.category)}</span><span style="margin-left:auto;font-size:11px;color:${selected===q.answer?'#719258':'#b88261'}">${selected===q.answer?'✓ 正解':selected===undefined?'未解答':'不正解'}</span></div>${q.script?`<h3 style="font-size:12px;margin-bottom:10px">音声スクリプト</h3><button class="voice-button" id="review-audio">${icon('volume')} もう一度聞く</button><div class="passage">${esc(q.script)}</div>`:''}${q.passage?`<div class="passage">${esc(q.passage)}</div>`:''}<p class="question-text">${esc(q.question)}</p>${q.options.map((opt,i)=>`<div class="option ${i===q.answer?'correct':i===selected?'incorrect':''}"><span class="option-num">${i+1}</span><span>${esc(opt)}${i===q.answer?'　✓ 正解':i===selected?'　← あなたの解答':''}</span></div>`).join('')}<div class="review-explanation"><b>正解：${q.answer+1}</b>${esc(q.explanation)}${q.zh&&!q.id.startsWith('x')?`<div class="zh">中文解析：${esc(q.zh)}</div>`:''}</div><div class="question-nav"><button class="button secondary" id="review-prev" ${reviewCursor===0?'disabled':''}>← 前の問題</button><button class="button" id="review-next" ${reviewCursor===r.questions.length-1?'disabled':''}>次の問題 →</button></div></section>`;if($('#review-audio'))$('#review-audio').onclick=()=>speak(q.script);$('#review-prev').onclick=()=>{stopVoice();reviewCursor--;renderQuestionReview(r);};$('#review-next').onclick=()=>{stopVoice();reviewCursor++;renderQuestionReview(r);};}
function renderReview(){const saved=memory.saved.map(getItem).filter(Boolean);main(`${heading('振り返るほど、確かな力に','復習ノート','気になったことばと、もう一度向き合いたい問題を。')}${activeNotice()}${notesPanelHTML()}<div class="section-heading"><h2>間違えた問題 <small>${memory.mistakes.length} 問</small></h2>${memory.mistakes.length?'<button class="button secondary" id="retry-mistakes">もう一度解く →</button>':''}</div>${memory.mistakes.length?memory.mistakes.map((m,i)=>`<div class="result-row" style="gap:15px"><div><span class="badge">${esc(m.question.category)}</span><p style="margin-top:5px;font-size:12px">${esc(m.question.question)}</p></div><button class="text-link" data-review-mistake="${i}" style="white-space:nowrap">解説を見る ↗</button></div>`).join(''):'<div class="empty"><h3>まだ間違えた問題はありません</h3><p>練習を提出すると、間違えた問題がここに集まります。</p><a class="button secondary" style="margin-top:20px" href="#exam">模擬試験へ →</a></div>'}<div id="result-review" style="margin-top:20px"></div><div class="section-heading" style="margin-top:35px"><h2>保存したことば <small>${saved.length} 項目</small></h2>${saved.length?'<button class="text-link" id="review-saved">カードで復習 →</button>':''}</div><div class="knowledge-grid">${saved.map(cardHTML).join('')||'<div class="empty"><p>学習カードのしおりを押すと、ここに保存できます。</p></div>'}</div>`);bindNoteEditor('general',$('#main'));if($('#retry-mistakes'))$('#retry-mistakes').onclick=()=>startExam('mistakes',memory.mistakes.map(m=>m.question));if($('#review-saved'))$('#review-saved').onclick=()=>startStudy(saved);$$('[data-review-mistake]').forEach(el=>el.onclick=()=>{const m=memory.mistakes[Number(el.dataset.reviewMistake)];reviewCursor=0;renderQuestionReview({questions:[m.question],answers:{[m.id]:m.selected}});$('#result-review').scrollIntoView({behavior:'smooth'});});}
function historyHTML(r){return `<div class="history-row"><span class="date">${new Date(r.date).toLocaleDateString('ja-JP')}</span><span>${esc(modeNames[r.mode]||'練習')}</span><span class="score">${r.correct} / ${r.total} 問</span><button class="text-link" data-history="${esc(r.id)}">結果を見る ↗</button></div>`;}
function renderProgress(){const totalDays=Object.values(memory.activity).filter(d=>d.items?.length||d.questions?.length).length;const questions=Object.values(memory.activity).reduce((a,d)=>a+(d.questions?.length||0),0);main(`${heading('自分の歩みを、見つめる','学習記録','小さな積み重ねを、目に見える自信に。')}<section class="stats"><div class="stat"><div class="stat-icon">${icon('flame')}</div><div><div class="stat-label">学習した日数</div><div class="stat-value">${totalDays}<small>日</small></div></div></div><div class="stat"><div class="stat-icon">${icon('book')}</div><div><div class="stat-label">習得した知識</div><div class="stat-value">${memory.known.filter(getItem).length}<small>項目</small></div></div></div><div class="stat"><div class="stat-icon">${icon('target')}</div><div><div class="stat-label">取り組んだ問題</div><div class="stat-value">${questions}<small>問</small></div></div></div></section>${weekHTML()}<div class="section-heading" style="margin-top:32px"><h2>学習コースごとの進捗</h2></div>${['kanji','vocab','grammar'].map(type=>{const data=knowledge(type),count=data.filter(x=>memory.known.includes(x.id)).length;return `<div class="panel" style="margin-bottom:12px"><div class="panel-title">${nameOf(type)}<span>${count} / ${data.length} 項目</span></div><div class="mini-progress"><span style="width:${data.length?count/data.length*100:0}%"></span></div></div>`;}).join('')}<section class="history-list"><div class="section-heading"><h2>試験・練習の履歴</h2><span class="badge">直近30回まで保存</span></div>${memory.history.map(historyHTML).join('')||'<div class="empty"><p>練習の結果は、ここに記録されます。</p><a href="#exam" class="button secondary" style="margin-top:18px">はじめての模擬試験 →</a></div>'}</section><div class="notice">記録はこのブラウザーにすぐ保存されます。GitHubに接続すると、メモ・習得・しおり・提出済みの試験結果を自分の保存先に同期できます。大切な記録はバックアップも保存してください。</div><div class="hero-actions"><button class="button secondary" id="export-data">記録をバックアップ</button><button class="button secondary" id="restore-data">バックアップを復元</button><input type="file" id="restore-file" accept="application/json,.json" class="file-input"></div>`);$('#export-data').onclick=()=>download('kotonoha-backup.json',{format:'kotonoha-backup-v1',data:memory});$('#restore-data').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=restoreBackup;}
function renderAbout(){main(`${heading('自分のペースで、ことばと向き合う','この学習室について','N1に挑むすべての学習者へ。')}<div class="about-body"><section><h2>言の葉 N1 の学び方</h2><p>画面と操作は日本語、文字・語彙・文法には日本語の解説と例文を添えています。「覚えた」で習得を記録し、しおりで復習ノートに保存できます。</p><p>練習・模擬試験の正解と解説は、提出後に表示されます。未解答は不正解として集計。計時試験では、タブを閉じても残り時間が進み、時間切れになると自動提出されます。</p></section><section><h2>収録範囲と教材の位置づけ</h2><div class="collection-header"><span>日本語で学ぶ知識カード</span><strong>${allKnowledge().length.toLocaleString()}<small>項目</small></strong><span class="badge">第2次拡充 · 2026年11月2日</span></div><div class="cover-grid">${['kanji','vocab','grammar'].map(type=>`<div><strong>${knowledge(type).length}</strong><span>${nameOf(type)}の収録項目</span></div>`).join('')}</div><p style="margin-top:17px">すべてのカードに、日本語解説・日本語例文を収録。語彙には社会・研究・仕事の表現、和語動詞、副詞・擬態語、慣用句などを含みます。文法は接続とニュアンスに加え、似た文型の使い分けを対比例文で確認できます。語彙には単語と連語の学習カードを、文字には代表的な読みと熟語を収録しています。</p><table><thead><tr><th>学習範囲</th><th>収録項目</th><th>位置づけ</th></tr></thead><tbody><tr><td>N1対策</td><td>${allKnowledge().filter(x=>focusOf(x)==='N1対策').length}項目</td><td>上級読解・聴解に向けた重点項目</td></tr><tr><td>関連知識</td><td>${allKnowledge().filter(x=>focusOf(x)==='関連知識').length}項目</td><td>意味のつながりや基礎の補強</td></tr></tbody></table><p>項目数は学習カードの数です。単語・連語・文型の比較を含み、同じ数の独立した公式出題項目を意味しません。今回の追加は ${allKnowledge().filter(isLatestAddition).length} 項目、前回の追加は ${allKnowledge().filter(isPreviousAddition).length} 項目です。学習一覧から追加回を選んで学べます。</p><p>分類は本教材の編集上の学習目安です。公式のレベル判定ではありません。学習一覧の「学習範囲」で絞り込めます。既存カードのIDは引き継がれるため、これまでの習得・しおりも保持されます。</p><p style="margin-top:17px">JLPT主催者は、漢字・語彙・文法の全項目を列挙した出題基準を公表していません。本教材はN1対策の重点学習集です。N1全知識点の網羅や、これだけでの合格を保証する教材ではありません。N2以下の基礎も含めた継続的な読書・聴取・学習が必要です。</p><p><a href="https://www.jlpt.jp/reference/pdf/guidebook_s_j.pdf" target="_blank" rel="noopener">公式ガイドブック・出題基準に関する説明 ↗</a></p></section><section><h2>試験形式と時間</h2><table><thead><tr><th>科目</th><th>問題数の目安</th><th>時間</th></tr></thead><tbody><tr><td>文字・語彙</td><td>25問</td><td rowspan="3">合わせて110分</td></tr><tr><td>文法</td><td>20問</td></tr><tr><td>読解</td><td>26問</td></tr><tr><td>聴解</td><td>30問</td><td>55分</td></tr></tbody></table><p>読解は短文4・中文9・長文4・統合理解3・主張理解4・情報検索2。聴解は課題理解5・ポイント理解6・概要理解5・即時応答11・統合理解3。問題数は公式の参考構成に合わせた目安で、実施回により変わる場合があります。読解だけの60分は学習用の設定です。</p><p>すべての問題・解説は本サイト独自の教材です。公式の過去問ではありません。聴解は端末の日本語合成音声を利用し、本試験の自然な録音・複数話者・一斉再生を完全に再現するものではありません。再生速度の調節と再聴ができます。</p><p>結果は正答率です。JLPTは尺度得点を使うため、正答率から公式得点や合否への換算はできません。</p><p><a href="https://www.jlpt.jp/guideline/testsections.html" target="_blank" rel="noopener">公式：試験科目と問題の構成 ↗</a><br><a href="https://www.jlpt.jp/topics/202208051659676565.html" target="_blank" rel="noopener">公式：N1聴解の時間・問題数の変更 ↗</a><br><a href="https://www.jlpt.jp/samples/sampleindex.html" target="_blank" rel="noopener">公式問題集・音声で学ぶ ↗</a></p></section><section><h2>教材を追加する</h2><p>知識カードは継続的に追加できる構成です。ご自身の学習ノートや、利用許諾を確認できる教材から用意した知識カードをJSONファイルで追加できます。サンプルと同じ形式で、文字・語彙・文法それぞれに日本語解説と例文を入力してください。同じIDの追加項目は置き換えられます。既存の教材は上書きされません。</p><div class="import-box"><button class="text-link" id="sample-content">追加用サンプルをダウンロード ↗</button><br><button class="button secondary" id="import-content">知識カードを追加</button><input type="file" id="content-file" class="file-input" accept="application/json,.json"></div></section><section><h2>記録とプライバシー</h2><p>習得項目・しおり・メモ・解答・試験履歴は、この端末のブラウザー内に保存されます。GitHub接続は任意です。ログイン後は自分の非公開の学習用リポジトリ、または公開ForkにJSONとして同期できます。公開Forkの記録は誰でも読めます。接続用トークンは記録ファイルやブラウザーの保存領域には保存しません。ブラウザーのデータを削除すると学習記録も失われます。学習記録ページからバックアップできます。</p></section></div>`);$('#sample-content').onclick=()=>download('kotonoha-content-sample.json',{grammar:[{id:'custom-g-001',title:'〜に至るまで',reading:'名詞＋に至るまで',category:'範囲',jp:'極端な例を挙げて、細部まで含むことを表す。',example:'企画から会場の飾り付けに至るまで、学生が担当した。'}],vocab:[],kanji:[]});$('#import-content').onclick=()=>$('#content-file').click();$('#content-file').onchange=importContent;}
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function validCard(x){return x&&['id','title','category','jp','example'].every(k=>typeof x[k]==='string'&&x[k].trim()&&x[k].length<12000)&&(!x.reading||typeof x.reading==='string')&&(!x.connection||typeof x.connection==='string');}
async function importContent(e){const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024)return toast('20MB以下のJSONファイルを選んでください。');try{const data=JSON.parse(await file.text());let count=0;for(const type of ['kanji','vocab','grammar']){if(data[type]!==undefined&&!Array.isArray(data[type]))throw Error();for(const x of data[type]||[]){if(!validCard(x))throw Error();count++;}}if(!count||count>10000)throw Error();for(const type of ['kanji','vocab','grammar']){memory.custom[type]||=[];for(const x of data[type]||[]){const clean={...x,id:`custom-${type}-${x.id.replace(/[^a-zA-Z0-9_-]/g,'').slice(0,150)}`};const idx=memory.custom[type].findIndex(y=>y.id===clean.id);if(idx>=0)memory.custom[type][idx]=clean;else memory.custom[type].push(clean);}}save();renderAbout();toast(`${count}項目を追加しました。`);}catch{toast('形式を確認してください。各項目に見出し・分類・日本語解説・例文が必要です。');}e.target.value='';}
function validQuestion(q){return q&&typeof q.id==='string'&&typeof q.category==='string'&&typeof q.question==='string'&&Array.isArray(q.options)&&q.options.length>=2&&q.options.length<=4&&q.options.every(x=>typeof x==='string')&&Number.isInteger(q.answer)&&q.answer>=0&&q.answer<q.options.length&&typeof q.explanation==='string'&&(q.zh===undefined||typeof q.zh==='string');}
async function restoreBackup(e){const file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw Error();const b=JSON.parse(await file.text());const d=b.data;if(d?.notes&&(!Object.values(d.notes).every(v=>typeof v==='string'&&v.length<=9000)))throw Error();if(b.format!=='kotonoha-backup-v1'||!d||!Array.isArray(d.known)||!d.known.every(x=>typeof x==='string')||!Array.isArray(d.saved)||!d.saved.every(x=>typeof x==='string')||!Array.isArray(d.history)||d.history.length>30||!d.history.every(r=>Array.isArray(r.questions)&&r.questions.every(validQuestion)&&typeof r.answers==='object'&&typeof r.id==='string'&&Number.isFinite(r.correct)&&Number.isFinite(r.total)&&Number.isFinite(Date.parse(r.date)))||!Array.isArray(d.mistakes)||!d.mistakes.every(m=>validQuestion(m.question))||!d.activity||typeof d.activity!=='object'||!Object.entries(d.activity).every(([date,a])=>/^\d{4}-\d{2}-\d{2}$/.test(date)&&Array.isArray(a.items)&&a.items.every(x=>typeof x==='string')&&Array.isArray(a.questions)&&a.questions.every(x=>typeof x==='string'))||!d.custom||!['kanji','grammar','vocab'].every(t=>Array.isArray(d.custom[t])&&d.custom[t].every(validCard)))throw Error();if(await confirmDialog('記録を復元しますか？','現在の学習記録を、バックアップ内の記録で置き換えます。進行中の試験は復元されません。','復元する')){memory={...d,notes:d.notes||{},active:null};save();renderProgress();toast('学習記録を復元しました。');}}catch{toast('有効な言の葉N1のバックアップを選んでください。');}e.target.value='';}
function confirmDialog(title,description,action){return new Promise(resolve=>{const d=$('#confirm-dialog');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(description)}</p><div class="confirm-actions"><button class="button secondary" id="confirm-cancel">戻る</button><button class="button" id="confirm-ok">${esc(action)}</button></div>`;let resolved=false;const close=value=>{if(resolved)return;resolved=true;d.close();resolve(value);};$('#confirm-cancel').onclick=()=>close(false);$('#confirm-ok').onclick=()=>close(true);d.addEventListener('cancel',()=>close(false),{once:true});d.addEventListener('close',()=>close(false),{once:true});d.showModal();});}
function openSearch(){const d=$('#search-dialog');if(!d.open)d.showModal();$('#global-search').value='';renderSearch('');$('#global-search').focus();}
function renderSearch(query){const q=query.trim().toLowerCase();const results=q?allKnowledge().filter(x=>[x.title,x.reading,x.jp].some(y=>String(y||'').toLowerCase().includes(q))):allKnowledge().filter(x=>memory.saved.includes(x.id));$('#search-results').innerHTML=!q&&!results.length?'<p class="search-hint">日本語のことば、読み方、意味から検索できます。</p>':results.slice(0,15).map(x=>`<button class="search-result" data-search-item="${esc(x.id)}"><span class="badge">${nameOf(x.type)}</span><span class="result-text"><b>${esc(x.title)}</b><small>${esc(x.jp)}</small></span>↗</button>`).join('')||'<p class="search-hint">該当する項目がありません。別のことばで検索してみましょう。</p>';}
$('#open-search').onclick=openSearch;$('#global-search').oninput=e=>renderSearch(e.target.value);document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}});
$('#menu-toggle').onclick=()=>{$('#sidebar').classList.toggle('open');$('.mobile-backdrop').classList.toggle('show');};const backdrop=document.createElement('div');backdrop.className='mobile-backdrop';document.body.append(backdrop);backdrop.onclick=()=>{$('#sidebar').classList.remove('open');backdrop.classList.remove('show');};
document.addEventListener('click',e=>{const el=e.target.closest('[data-item],[data-save],[data-filter],[data-page],[data-answer],[data-question-step],[data-question-index],[data-start-exam],[data-start-daily],[data-category-practice],[data-history],[data-search-item]');if(!el)return;const d=el.dataset;if(d.item){e.preventDefault();const item=getItem(d.item);if(item)startStudy(allKnowledge().filter(x=>x.type===item.type),item.id);}else if(d.save){toggleSave(d.save);render();}else if(d.filter){catalog.status=d.filter;catalog.page=0;renderCatalog(currentRoute());}else if(d.page){catalog.page+=Number(d.page);renderCatalog(currentRoute());window.scrollTo({top:0,behavior:'smooth'});}else if(d.answer!==undefined){const a=memory.active;if(!a||a.phase!=='running')return;if(a.deadline&&a.deadline<=Date.now()){finishSection();return;}const q=sectionData()[a.cursor];a.answers[q.id]=Number(d.answer);save();$$('[data-answer]').forEach(button=>{button.classList.toggle('selected',button.dataset.answer===d.answer);button.setAttribute('aria-checked',button.dataset.answer===d.answer);});const map=$(`[data-question-index="${a.cursor}"]`);map?.classList.add('answered');const counter=$('#answered-count');if(counter)counter.textContent=Object.keys(a.answers).length;}else if(d.questionStep!==undefined||d.questionIndex!==undefined){stopVoice();const a=memory.active;if(!a)return;a.cursor=d.questionIndex!==undefined?Number(d.questionIndex):a.cursor+Number(d.questionStep);save();renderActive();window.scrollTo({top:0,behavior:'smooth'});}else if(d.startExam){startExam(d.startExam);}else if('startDaily'in d){const pool=allKnowledge().filter(x=>x.type==='vocab'&&!memory.known.includes(x.id));startStudy(pool.length?pool:allKnowledge());}else if(d.categoryPractice){const pool=d.kind==='reading'?reading():listening();startExam('practice',pool.filter(q=>q.category===d.categoryPractice));}else if(d.history){reviewedResult=memory.history.find(r=>r.id===d.history);if(location.hash!=='#exam')location.hash='exam';else if(reviewedResult)renderResult(reviewedResult);}else if(d.searchItem){$('#search-dialog').close();const item=getItem(d.searchItem);if(item)startStudy(allKnowledge().filter(x=>x.type===item.type),item.id);}});

function noteEditorHTML(id){return `<section class="personal-note"><label for="personal-note-${esc(id)}">自分のメモ</label><textarea id="personal-note-${esc(id)}" data-note-input maxlength="9000" rows="4" placeholder="使い分け、気づいたこと、自分で作った例文を。">${esc(memory.notes?.[id]||'')}</textarea><div class="note-actions"><button class="button secondary" data-note-save>メモを保存</button><button class="text-link" data-note-history>変更履歴</button><button class="text-link" data-note-delete>削除</button><span>端末に自動保存 · GitHub接続中はまとめて同期</span></div></section>`;}
function bindNoteEditor(id,rootElement){const input=$('[data-note-input]',rootElement);if(!input)return;const store=()=>{memory.notes||={};memory.notes[id]=input.value;save();};input.oninput=store;$('[data-note-save]',rootElement).onclick=async()=>{store();if(cloud?.current().account){try{await cloud.flush();toast('GitHubにメモを保存しました。');}catch(error){toast(error.message);}}else toast('メモをこの端末に保存しました。');};$('[data-note-delete]',rootElement).onclick=()=>{input.value='';store();toast('メモを削除しました。同期中の履歴は変更履歴に残ります。');};$('[data-note-history]',rootElement).onclick=()=>showNoteHistory(id,input);}
function showNoteHistory(id,input){const versions=cloud?.versions(id)||[];if(!versions.length)return toast('GitHub接続後、同期したメモの変更履歴を確認できます。');let dialog=$('#note-history-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='note-history-dialog';dialog.className='sync-dialog';document.body.append(dialog);}dialog.innerHTML=`<button class="dialog-close" id="note-history-close" aria-label="閉じる">×</button><h2>メモの変更履歴</h2><p class="sync-description">ほかの端末の編集を含む直近の履歴です。復元すると新しい変更として保存します。</p>${versions.map((v,i)=>`<article class="note-version"><small>${esc(new Date(v.clock).toLocaleString('ja-JP'))}</small><p>${esc(v.value||'（削除済み）')}</p><button class="text-link" data-restore-note="${i}">この内容を復元する →</button></article>`).join('')}`;$('#note-history-close').onclick=()=>dialog.close();$$('[data-restore-note]',dialog).forEach(button=>button.onclick=()=>{input.value=versions[Number(button.dataset.restoreNote)].value;input.oninput();dialog.close();toast('メモを復元しました。');});dialog.showModal();}
function notesPanelHTML(){const entries=Object.entries(memory.notes||{}).filter(([id,text])=>id!=='general'&&text);return `<section class="panel notes-panel"><div class="section-heading"><h2>自分のメモ <small>${entries.length} 件</small></h2><button class="text-link" data-cloud-open>GitHub同期 →</button></div>${noteEditorHTML('general')}${entries.length?`<div class="saved-notes">${entries.map(([id,text])=>`<a class="saved-note" href="#review" data-item="${esc(id)}"><b>${esc(getItem(id)?.title||id)}</b><p>${esc(text.slice(0,140))}${text.length>140?'…':''}</p></a>`).join('')}</div>`:'<p class="sync-description">知識カードで保存したメモも、ここに集まります。</p>'}</section>`;}
function updateCloudStatus(state){const button=$('#github-account');if(button)button.textContent=state.account?`@${state.account.login} · ${state.status}`:'GitHubで学習記録を同期';const profile=$('#github-profile');if(profile)profile.textContent=state.account?'@'+state.account.login:'GitHubに接続する';}
function applyCloudSnapshot(snapshot,user){const nextKey=user?`${key}:user:${user.id}`:key;let cached=null;try{cached=JSON.parse(localStorage.getItem(nextKey)||'null');}catch{}const active=cached?.active||null;const hadActive=!!memory.active;memory={...emptyMemory(),...(cached||{}),...(snapshot||{}),active};storageKey=nextKey;try{localStorage.setItem(storageKey,JSON.stringify(memory));}catch{storageOK=false;}if(!hadActive&&!$('#study-dialog').open)render();else if(nextKey!==key&&active===null&&hadActive)render();}

document.addEventListener('click',e=>{if(e.target.closest('[data-cloud-open]'))cloud?.open();});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
window.addEventListener('beforeunload',stopVoice);
render();
if(window.KotonohaCloud){cloud=window.KotonohaCloud.create({getSnapshot:()=>memory,getGuestSnapshot:()=>{try{return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}},applySnapshot:applyCloudSnapshot,onStatus:updateCloudStatus,toast});$('#github-account').onclick=()=>cloud.open();$('#github-profile').onclick=()=>cloud.open();cloud.init().catch(error=>toast(error.message));}
})();
